INSERT INTO "case_studies" (
    "title",
    "experience_id",
    "summary",
    "content",
    "slug",
    "published_at",
    "featured",
    "updated_at",
    "created_at",
    "meta_title",
    "meta_description"
) VALUES (
    'Trust, But Re-Execute',
    (SELECT id FROM "experiences" WHERE "title" ILIKE '%seekout%' OR "company" ILIKE '%seekout%' LIMIT 1),
    '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"An agent that writes analytics reports will eventually invent a statistic. Ours announced a 26.7% reply rate no query produced. This is how Spot''s report generation was rebuilt so a report cannot state a number it didn''t compute — and the blind, adversarial scoreboard that proves it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0}],"direction":"ltr"}}',
    '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Context","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Spot is SeekOut''s agentic AI recruiter. One of the things it does is write analytics reports: a hiring manager asks \"how is the senior pipeline actually looking,\" a multi-turn agent probes forty-odd hiring tables, decides what story the data tells, and lays the answer out as an editorial brief — KPI strips, funnels, quote cards, prose that reads like an analyst wrote it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The hard part isn''t making a model write. Models love to write. The hard part is that an analytics report makes claims, and claims in a hiring report get acted on. Someone reads \"39 candidates presented\" and walks into a Monday meeting holding that number.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''d spent weeks making these reports beautiful. Rebuilt the component library to one visual language. Made the charts stop lying — gauges that show the real value instead of capping it, ranked lists that keep their sort. Blind judges compared the rebuilt output head-to-head against the old build and preferred it 11 to 0. Presentation scores hit an all-time high.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The breaking point came when I ran fact verification against that golden battery for the first time. The truth score came back 3.14 out of 5: sixteen defects a reader would act on and three invented figures, sitting under the best-looking reports we''d ever produced. The flagship example was a cover tile announcing a ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"26.7% candidate reply rate","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" that no query anywhere in the system produced. The model wanted a strong close for its recommendation section, so it manufactured one.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We had been optimizing how reports looked, with a scoreboard that could not see whether they were true.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Problem","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Call it scoreboard blindness. Every evaluation we had — aesthetic judges, layout scores, edit-success rates — measured polish, and polish and truth turn out to be fully independent variables. Underneath the pretty pages, four distinct failure modes were compounding:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Confident invention","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": prose stating figures no query produced. The 26.7% tile is the poster child, but \"24 of 36 candidates contacted\" with zero backing SQL is the same disease in a quieter outfit.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":2,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Wrong-column funnels","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": a pipeline funnel computed off a status column the schema explicitly forbids for stage counting — producing \"5 presented\" directly beneath a cover tile saying 39 were presented. Both numbers rendered beautifully.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":3,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Cross-panel contradiction","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": the same metric appearing in two panels with two different values, because each panel''s query made its own choices and nothing ever compared them.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":4,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The eyeball ceiling","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": a single report can carry a dozen panels of SQL. Nobody reviews ninety panels of SQL by hand, and the one person who tries stops being able to see anything else.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr","listType":"bullet"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"None of this is a prompt problem you can nag your way out of. A prompt is a suggestion. The model had plenty of suggestions already.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Solution","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The whole rebuild rests on one split: ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"taste lives in the prompts, the meaning of each column lives with the data, and correctness lives in code.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No sweeping data rules in the prompts. No aesthetic opinions in the lints. One authoring model, followed by checking stages that try to break what it wrote — using code, not taste.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Explore-First Authoring: No Data Pack, No Excuses","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The old pipeline handed the author a pre-built data pack and a ~7,000-token schema registry dumped into its prompt. It trusted the handoff, and the handoff was always slightly wrong. The rebuilt author gets nothing. It discovers the schema itself through three tools — list the tables, preview one, run a query — writes every query it intends to show, and emits the whole report in one pass. The meaning of each column (what it counts, what it must never be used to count) moved out of the prompt and into schema metadata the tools serve, which is the single counting authority for author and judge alike.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Server Grounding: The Page Shows What the Database Returned","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Every panel''s SQL is re-executed server-side, read-only, through a static-analysis stack that walks the query''s AST: table allowlists, column existence, tenant scoping, double-count detection. A panel that fails gets one mechanical repair attempt, then it''s dropped. The numbers on the page are, structurally, the numbers the database returned — not the numbers the model remembers seeing.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"A Judge That Cannot Type","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The last pass is an LLM judge with one load-bearing constraint: it cannot write a number or a sentence of its own. Every value it touches comes from a pure function reading real queried rows. It sweeps every prose figure against the actual result sets — unit-aware, so a fabricated \"26.7%\" can no longer confirm itself against some unrelated count — re-lints every panel, and hunts cross-panel contradictions. When it finds a bad figure, its tools rebind the figure to the intended cell or delete the sentence cleanly. The judge decides ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"where","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":" the problem is. The database decides ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"what''s true","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":".","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Fail Closed: Silence Is Failure","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"If the judge pass doesn''t complete, the report doesn''t ship. If more than a third of a report''s panels get dropped, no artifact is produced at all — a report that''s mostly holes is not a report. This rule earned its keep in the worst way: an early version of the fact-checker was dying silently on large reports and passing them unjudged, and the scores moved in a direction that made no sense until we found the swallowed exception. Now silence counts as failure. An empty answer beats a confident wrong one.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"h3","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What I considered and rejected","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better prompts.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" About 250 lines of hardcoded data doctrine — canonical funnel definitions, per-rate SQL formulas — already lived in the prompts, and the model was penalized for obeying them. All of it came out. Prompts keep the taste; walls keep the rules.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":2,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Keeping the pre-generation data pack.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No. An author handed a digest trusts the digest. Making it look at the real tables is slower and correct, in that order.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":3,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Letting the judge free-write corrections.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No. A judge that can type a number is just a second author with better branding.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":4,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Wholesale regeneration on every edit.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" No. When we studied 139 isolated edits, the rebuild-everything path caused 7 of the 8 damaging incidents in the corpus. Edits became narrow typed operations — rename runs no queries, a filter change re-runs one panel — and the regression rate fell to 1 in 45.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr","listType":"bullet"},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The Impact","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Measured by a fixed 15-prompt battery, blind judges pinned across runs, and deterministic SQL re-execution of every panel — the same scoreboard that caught the problem, so the deltas mean something. One rule with teeth: a single wrong number a reader would act on caps that report at 1 out of 5, no matter how good everything else is.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"tag":"ul","type":"list","start":1,"format":"","indent":0,"version":1,"children":[{"type":"listitem","value":1,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Invented figures: 3 per audit run → 0.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" The final battery checked 56 panels and found zero wrong.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":2,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Reader-impacting defects down 94%","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" — 18 → 1 — across five audit runs in roughly thirty hours.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":3,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Two funnel report types went from 1/5 to a perfect 5/5","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" once column meaning moved out of prompts and into schema metadata. Same model, same asks; the only thing that changed was where the truth lived.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":4,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Perceived latency down 62%","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":": generation streams its outline mid-loop, so the first visible structure lands at ~47 seconds instead of ~125. The rigor underneath is unchanged; the spinner just stopped hogging the stage.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"listitem","value":5,"format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What I''m especially proud of is the ratchet: every real defect the battery finds becomes a permanent regression test. The scoreboard only gets meaner.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"}],"direction":"ltr","listType":"bullet"},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What It Cost","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The honest column. A full generation now runs about 220 seconds — schema exploration, server grounding, and a three-sweep judge pass all cost real time, and no amount of streaming makes that free. A fail-closed pipeline sometimes ships nothing: an ungroundable ask produces no report, which is the correct behavior and still a conversation you have to have with users. And the first re-architecture attempt scored ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"worse","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":" than the baseline it replaced — the judge was failing open and nobody knew — which was a humbling week, and also exactly the kind of failure the measurement loop exists to catch.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"horizontalrule","version":1},{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Closing","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The rule is simple and load-bearing: ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"no model is ever the source of truth — every number a report shows is one the database returned.","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" The model''s job is the story. The database''s job is the numbers.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Somewhere in the audit archive there''s still that handsome July report with its invented 26.7%. I keep it around. It''s the best argument the pipeline ever made for itself.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textStyle":"","textFormat":0}],"direction":"ltr"}}',
    'seekout-spot-trust-but-re-execute',
    '2026-08-24T07:43:22.194Z',
    false,
    '2026-08-24T07:43:22.194Z',
    '2026-08-24T07:43:22.194Z',
    'Trust, But Re-Execute — Fact-Checked AI Report Generation',
    'How SeekOut Spot''s agentic report generation was rebuilt to be correct by construction: explore-first authoring, server-side SQL re-execution, a judge that cannot type numbers, and a blind audit battery that cut reader-impacting defects 94%.'
);

